// A TV box publica um Last Will ({"online": false}) que o broker entrega
// quando ela some da rede. Aqui isso vira um evento de alarme, para reusar
// o flow de push que ja existe.
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') return null;

const id = msg.topic.split('/')[1];
if (!id) return null;

// voltou: libera para alertar de novo na proxima queda
if (p.online === true) { flow.set('off_' + id, 0); return null; }
if (p.online !== false) return null;

// status retido pode chegar repetido; nao repete o alerta em 1 min
const now = Date.now();
if (now - (flow.get('off_' + id) || 0) < 60000) return null;
flow.set('off_' + id, now);

msg.topic = 'devices/' + id + '/alarme/event';
msg.payload = JSON.stringify({ type: 'tvbox_offline', name: 'TV box' });
msg.qos = 1;
msg.retain = false;
return msg;
